-- Conquest of Azeroth road caravans: seven rideable Caravan Carts that run roads out and back: the six
-- starting-zone roads (Elwynn, Dun Morogh, Teldrassil, Tirisfal, Mulgore, Durotar) and the road from
-- Westfall through Goldshire to the Three Corners (a second Elwynn Caravan Cart). Generated by
-- .agents/plans/coa-world/tools/gen_caravans.py from .agents/plans/coa-world/research/caravans/PLAN.md.
--
-- WHAT RIDES AND HOW
--   The cart is a vehicle creature (CoA Vehicle.dbc 1527-1532). Its Caravan Master sits in the driver
--   seat (index 1) and its draft beasts in the draft seats (2 and 3) as vehicle accessories, so a click
--   (46598 Ride Vehicle Hardcoded, npc_spellclick_spells) always lands in a passenger seat. No seat can
--   control the cart, so it keeps its road path while players ride; the ride is refused in combat.
--   The Pack Kodo cart (50470, Mulgore and Durotar) has its kodos in the model; the invisible Caravan
--   Harness 9303000 fills its empty draft seat 2 so a second rider does not land on the road.
--   Beasts loop the Run animation through CoA's aura 992478 RUN (State).
--   Each cart runs its road at 8 yd/s (RUN) and waits 45 s at each stop facing the way it leaves: it
--   turns back at the two end stops, and the Durotar and Westfall carts also stop on both passes at a
--   middle stop. Paths are points 1..N out and N-1..2 back, smoothTransition 1 (one spline per leg
--   between stops).
--
-- WHERE EACH VALUE COMES FROM
--   entries, names, IconName, type, type_flags, displays  SOURCED-CACHE creaturecache (CoA mode).
--   seat layouts, spells 46598 and 992478, model sizes  SOURCED-CLIENT (Vehicle, VehicleSeat, Spell,
--     CreatureDisplayInfo, CreatureModelData).
--   cart -> vehicle mapping, masters, beasts, factions, one cart per road  INFERRED (research/caravans/
--     evidence.md, PLAN.md section 2). 9303000 Caravan Harness is a new INFERRED helper.
--   route points  hand-traced on the CoA road textures (research/caravans/routes, car2, car2-durotar),
--     every z the server floor (DERIVED, surface.py); hand fixes are noted on the points themselves.
--   routes  the user (2026-09-24): Goldshire - Northshire kept; Westfall - Three Corners through Elwynn;
--     Orgrimmar - Razor Hill - Sen'jin Village; Mulgore stays on the road at the Bloodhoof junction.
--     Dun Morogh, Teldrassil and Tirisfal: starting-area exit and first town next to the Novice Rider
--     SuperTrack points (INFERRED). The exact stop spots are INFERRED from the road layout.
--   speed 8.0, stops 45 s, combat condition, visibility Large  INFERRED.
--
-- Id blocks: creature guid 9006000-9006199 (9006000-9006006 used), creature entry 9303000-9303099
--   (9303000 used), waypoint path 900600000-900619999 (guid x 100). CoA entries 50470, 50473-50476,
--   314860, 314864-314873 (not 314862/314863) and creature_model_info 31290, 50439, 50440 are created
--   here; no other scope writes them. No stock row is changed.

-- ---------------------------------------------------------------------------
-- 1. Templates: carts, Caravan Masters, draft beasts and the Caravan Harness
-- ---------------------------------------------------------------------------
-- Elwynn: cart 50476 Elwynn Caravan Cart (vehicle 1532), driver 314872 Human Caravan Master, draft seat 2 314871
--   Brown Horse, seat 3 314871 Brown Horse
-- Dun Morogh: cart 50474 Dun Morogh Caravan Cart (vehicle 1530), driver 314868 Dwarf Caravan Master, draft seat 2
--   314867 White Riding Ram Mount, seat 3 314867 White Riding Ram Mount
-- Teldrassil: cart 50475 Teldrassil Caravan Cart (vehicle 1531), driver 314870 Nightelf Caravan Master, draft seat 2
--   314869 Swift Stormsaber, seat 3 314869 Swift Stormsaber
-- Tirisfal: cart 50473 Tirisfal Caravan Cart (vehicle 1529), driver 314864 Undead Caravan Master, draft seat 2
--   314865 Purple Skeletal Warhorse, seat 3 314866 Green Skeletal Warhorse
-- Mulgore: cart 50470 Pack Kodo Caravan Cart (vehicle 1527), driver 314860 Tauren Caravan Master, draft seat 2
--   9303000 Caravan Harness
-- Durotar: cart 50470 Pack Kodo Caravan Cart (vehicle 1527), driver 314873 Durotar Caravan Master, draft seat 2
--   9303000 Caravan Harness
-- Westfall: cart 50476 Elwynn Caravan Cart (vehicle 1532), driver 314872 Human Caravan Master, draft seat 2 314871
--   Brown Horse, seat 3 314871 Brown Horse
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `subname` = VALUES(`subname`), `IconName` = VALUES(`IconName`), `minlevel` = VALUES(`minlevel`), `maxlevel` = VALUES(`maxlevel`), `exp` = VALUES(`exp`), `faction` = VALUES(`faction`), `npcflag` = VALUES(`npcflag`), `speed_walk` = VALUES(`speed_walk`), `speed_run` = VALUES(`speed_run`), `BaseAttackTime` = VALUES(`BaseAttackTime`), `RangeAttackTime` = VALUES(`RangeAttackTime`), `unit_class` = VALUES(`unit_class`), `unit_flags` = VALUES(`unit_flags`), `unit_flags2` = VALUES(`unit_flags2`), `type` = VALUES(`type`), `type_flags` = VALUES(`type_flags`), `VehicleId` = VALUES(`VehicleId`), `AIName` = VALUES(`AIName`), `MovementType` = VALUES(`MovementType`), `HealthModifier` = VALUES(`HealthModifier`), `ManaModifier` = VALUES(`ManaModifier`), `ArmorModifier` = VALUES(`ArmorModifier`), `RegenHealth` = VALUES(`RegenHealth`), `flags_extra` = VALUES(`flags_extra`), `ScriptName` = VALUES(`ScriptName`);

DELETE FROM `creature_template_model` WHERE `CreatureID` IN (50470, 50473, 50474, 50475, 50476, 314860, 314864, 314865, 314866, 314867, 314868, 314869, 314870, 314871, 314872, 314873, 9303000);

-- The three cart displays had no creature_model_info row, without which a creature cannot load
-- (Creature.cpp:526-532). BoundingRadius is the client GeoBox half-width.
DELETE FROM `creature_model_info` WHERE `DisplayID` IN (31290, 50439, 50440);

-- Masters and beasts are seen from 200 yd like their cart; the beasts loop the Run animation (992478).
DELETE FROM `creature_template_addon` WHERE `entry` IN (314860, 314864, 314865, 314866, 314867, 314868, 314869, 314870, 314871, 314872, 314873);

-- ---------------------------------------------------------------------------
-- 2. Boarding: spell-click (clicker casts 46598 on the cart, friendly players only), refused in combat
-- ---------------------------------------------------------------------------
DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` IN (50470, 50473, 50474, 50475, 50476);

DELETE FROM `conditions` WHERE `SourceGroup` IN (50470, 50473, 50474, 50475, 50476) AND `SourceTypeOrReferenceId` = 18 AND `SourceEntry` = 46598;

-- ---------------------------------------------------------------------------
-- 3. Crew: driver and draft seats (template accessories; per spawn for the shared Pack Kodo cart)
-- ---------------------------------------------------------------------------
DELETE FROM `vehicle_template_accessory` WHERE `entry` IN (50470, 50473, 50474, 50475, 50476);

DELETE FROM `vehicle_accessory` WHERE `guid` IN (9006000, 9006001, 9006002, 9006003, 9006004, 9006005, 9006006) OR `guid` BETWEEN 9006000 AND 9006199;

